// This file is generated by AI.

// 状态栏: LSP 状态、诊断数、光标位置、活动文档字数。

import { useAppStore } from '../state/store';

export function StatusBar() {
  const lspStatus = useAppStore((s) => s.lspStatus);
  const lspError = useAppStore((s) => s.lspError);
  const cursor = useAppStore((s) => s.cursor);
  const activePath = useAppStore((s) => s.activePath);
  const documents = useAppStore((s) => s.documents);
  const diagnostics = useAppStore((s) => s.diagnostics);

  const activeDoc = documents.find((d) => d.path === activePath) ?? null;
  const diagCount = activePath ? (diagnostics[activePath]?.length ?? 0) : 0;
  const errors = activePath ? (diagnostics[activePath]?.filter((d) => d.severity === 1).length ?? 0) : 0;
  const charCount = activeDoc?.content.length ?? 0;

  return (
    <div className="status-bar" title={lspError ?? undefined}>
      <span className={`lsp-status lsp-${lspStatus}`}>
        LSP:{' '}
        {lspStatus === 'ready'
          ? '就绪'
          : lspStatus === 'connecting'
            ? '连接中'
            : lspStatus === 'error'
              ? '错误'
              : '未连接'}
      </span>
      <span className="status-diag">
        诊断: {diagCount}
        {errors > 0 ? ` (错误 ${errors})` : ''}
      </span>
      <span className="status-spacer" />
      {cursor ? (
        <span className="status-cursor">
          行 {cursor.line}, 列 {cursor.column}
        </span>
      ) : null}
      <span className="status-chars">字符 {charCount}</span>
    </div>
  );
}
